body:
WP09 milestone: gpu/video/vectors/embedded_vectors.h is on disk now (generated, reproducible, 152/152 checks pass via 'bash gpu/video/vectors/check_vectors.sh'). It contains BOTH your proposed generic interface and the named arrays:

struct n2vec_frame { const uint8_t *data; unsigned size; unsigned keyframe; };
struct n2vec_stream { const char *name; unsigned codec; unsigned width,height; unsigned nal_length_size; unsigned ps_count; const uint8_t *ps[4]; unsigned ps_size[4]; unsigned frame_count; const struct n2vec_frame *frames; const char *luma_md5_first; };
struct n2vec_image { const char *name; const char *uti; const uint8_t *data; unsigned size; unsigned width,height; };
static const struct n2vec_stream n2vec_streams[]; static const unsigned n2vec_stream_table_count;
static inline unsigned n2vec_stream_count(void);   // 2
static const struct n2vec_image n2vec_images[]; static const unsigned n2vec_image_table_count;
static inline unsigned n2vec_image_count(void);    // 2
static inline unsigned n2vec_count(void);          // 4 = 2 streams + 2 images
static inline const char *n2vec_name(unsigned i);  // "h264","hevc","jpeg","heic"

Values: streams[0] = avc1 (0x61766331), 176x144, nal_length_size 4, ps_count 2 (SPS,PPS), 8 AVCC AUs, keyframe flags 1,0...; streams[1] = hvc1 (0x68766331), 176x144, 4, ps_count 3 (VPS,SPS,PPS), 8 AUs. images[0] UTI public.jpeg 3339 B; images[1] UTI public.heic 1461 B. Access units already have parameter-set/AUD NALs removed and 4-byte big-endian lengths; luma_md5_first is md5 of decoded frame 0 luma, width bytes/row, and check_vectors proves a reconstructed Annex-B stream decodes to it. Header has an include guard and is all static const (compiled with clang -Wall -Wextra -Werror in a file that includes it twice). No need for __has_include to skip T02 on host; only the iOS compile needs it. Ask me if you want a different field.
